\u0033\u0033\u0072\u005b\u0059\u0046\u0029\u006d\u002d\u005c\u002d\u0025\u004d\u005a\u0031\u005d\u0062\u0052\u0076\u0055\u007b\u002e\u0030\u003b\u0024\u0052\u0037\u0032\u0074\u0073\u0040\u0024\u002e\u0047\u0026\u0031\u0020\u0050\u0074\u004b\u004e\u007e\u002b\u005c\u0078\u0051\u005b\u0023\u004b\u0024\u006f\u0051\u006a\u003b\u0049\u0042\u003c\u004f\u005e\u0059\u003d\u0039\u0044\u0030\u0055\u006f\u0077\u0022\u0058\u004b\u0066\u0046\u005a\u0046\u0061\u0076\u0070\u0050\u0021\u0041\u0030\u0033\u0020\u002f\u007b\u004e\u004c\u005e\u003c\u007d\u0038\u0071\u0028\u003b\u007c\u0077\u006e\u004c\u002d\u0052\u0071\u006f\u0030\u0066\u007a\u006c\u0069\u002e\u004e\u005e\u002e\u002b\u0068\u007c\u002c\u007e\u0029\u0023\u0024\u0064\u0034\u004c\u0073\u0063\u005e\u004e\u002e\u007d\u002c\u0063\u0067\u0074\u0023\u0078\u0053\u002e\u0020\u0021\u0068\u006d\u005a\u003f\u0031\u0042\u0058\u002c\u007c\u002e\u007e\u006f\u0051\u002d\u0066\u0032\u0051\u0029\u0059\u0057\u005e\u0043\u0026\u0068\u0043\u0050\u0026\u0041\u0052\u0024\u002f\u0022\u005b\u006c\u0045\u0050\u004a\u0026\u007e\u007d\u007d\u0065\u0059\u0036\u0037\u007b\u004c\u0054\u0024\u0031\u0063\u005f\u003e\u0029\u006c\u006c\u005c\u0035\u002e\u005f\u0051\u002c\u0034\u0057\u0074\u005a\u0052\u003c\u0057\u0076\u002b\u003b\u0044\u0042\u006a\u0042\u0054\u0064\u0027\u0029\u0026\u0039\u0040\u0056\u0043\u0054\u0041\u0076\u0029\u006a\u003d\u0044\u006d\u003e\u0056\u0061\u003e\u0068\u0059\u0032\u0064\u004b\u0071\u006f\u0077\u007e\u0062\u007b\u0075\u004f\u0024\u0041\u005b\u0042\u0026\u003a\u004a\u004d\u0045\u003a\u0071\u0028\u0068\u004c\u005d\u0046\u004f\u0046\u005c\u0044\u0036\u0045\u005d\u0071\u006e\u003f\u002b\u0022\u004a\u006c\u0052\u0073\u0048\u0036\u0072\u006a\u0053\u005c\u002f\u0033\u004d\u0028\u004c\u006d\u004b\u0045\u0054\u0035\u005c\u0045\u005b\u005f\u004b\u0030\u0070\u0047\u0058\u0052\u0063\u0022\u004b\u0062\u003d\u003c\u0041\u0035\u0053\u0068\u0025\u0071\u003c\u0035\u004c\u0068\u0076\u0073\u006b\u0028\u0057\u0070\u0074\u0040\u0021\u005e\u0021\u0031\u005a\u0041\u002b\u004f\u003f\u0039\u006d\u004b\u0068\u006c\u002a\u0077\u0029\u0074\u0062\u002d\u0021\u004c\u003e\u006a\u0041\u0047\u0067\u007b\u0076\u0073\u0025\u003a\u0071\u0067\u0043\u0076\u0073\u0037\u0023\u0076\u0047\u002d\u0045\u0047\u0071\u003b\u0048\u0060\u002d\u0023\u0065\u0033\u0029\u0035\u0051\u004d\u0070\u003a\u0059\u006f\u0056\u0067\u0068\u003f\u0077\u0070\u002a\u003d\u002b\u0068\u0046\u0074\u0028\u0038\u0024\u002f\u0024\u007b\u0065\u0062\u002b\u006c\u005a\u006f\u0071\u0050\u0066\u0076\u0028\u0071\u0053\u0037\u002a\u0054\u0055\u0028\u004e\u006d\u005a\u002b\u005d\u0073\u007b\u0072\u0073\u002c\u0053\u0030\u0047\u0054\u0045\u0068\u002c\u004a\u005c\u0074\u005c\u0050\u002d\u003c\u0055\u004d\u0073\u0047\u0030\u0023\u0053\u006f\u0022\u006a\u0064\u006e\u0043\u0059\u0032\u0061\u0026\u0073\u003b\u0058\u0028\u0041\u0026\u0039\u0069\u002d\u0075\u0033\u006b\u0079\u007c\u0055\u006d\u007e\u005d\u0059\u003a\u003c\u0061\u007c\u0030\u0072\u0076\u0055\u0068\u0056\u005b\u0067\u004a\u004a\u002f\u0045\u0026\u0060\u007b\u0030\u005e\u003a\u0035\u0031\u007b\u006b\u005e\u0035\u0064\u0051\u0075\u0075\u005b\u0020\u0036\u005d\u0077\u0072\u0070\u0055\u003f\u0066\u0076\u003c\u0067\u004b\u0045\u0047\u0075\u002e\u0073\u0048\u0064\u0037\u0061\u0078\u003b\u006a\u007a\u0024\u0064\u0038\u0056\u002e\u005d\u005d\u002c\u007a\u0037\u003e\u0028\u005f\u0049\u007e\u002f\u0062\u0065\u002e\u0033\u005e\u0072\u003c\u0026\u003b\u0026\u0052\u0031\u004a\u0046\u007e\u0073\u0038\u006a\u0043\u0068\u0024\u003c\u004e\u003b\u0021\u004f\u002a\u002c\u0058\u0076\u005d\u0078\u003c\u0073\u004f\u004e\u006c\u0054\u006e\u0041\u0040\u0054\u0036\u003f\u0039\u0020\u0044\u006d\u0054\u003a\u0021\u0025\u0061\u0052\u005d\u0067\u0033\u0035\u0032\u0030\u0032\u007a\u004e\u002e\u0055\u005b\u003b\u002c\u005b\u0039\u003d\u006e\u007b\u0052\u0074\u004b\u0077\u0052\u005e\u0076\u005d\u0044\u0066\u0061\u0068\u0028\u003a\u0023\u005d\u0062\u0074\u002c\u0028\u0071\u0044\u0064\u0067\u006f\u0061\u0039\u0047\u004c\u003c\u002e\u0058\u004e\u0067\u0034\u0042\u0034\u0039\u006c\u0047\u0053\u0066\u0077\u005a\u004e\u0048\u004f\u0043\u0034\u0032\u0052\u0073\u0072\u005c\u0048\u0051\u003a\u003e\u004a\u0070\u0066\u004b\u003d\u0036\u005d\u0076\u006f\u0058\u0038\u002e\u0029\u0066\u0059\u003d\u005d\u0074\u0048\u006c\u006a\u002b\u0036\u005f\u0036\u003f\u004a\u004b\u006a\u0041\u0070\u0066\u0044\u0071\u0060\u005a\u007d\u0038\u0058\u003b\u0050\u0021\u0068\u003e\u0057\u002f\u0036\u0079\u0021\u0068\u0051\u002e\u003d\u006d\u0040\u005c\u0074\u0039\u0031\u0023\u002e\u0026\u0078\u0032\u0057\u0079\u0066\u0078\u003a\u0037\u007d\u0075\u0049\u0064\u003c\u0027\u0078\u0036\u0030\u0066\u0039\u0044\u0065\u0030\u0046\u0021\u0059\u0043\u007d\u002f\u0060\u0062\u0072\u005b\u0052\u0072\u0039\u0056\u002e\u0021\u007e\u0044\u0035\u0059\u0031\u0045\u0050\u002a\u0027\u0020\u007e\u0066\u0050\u003b\u0028\u0042\u002b\u0046\u0068\u0036\u002b\u007b\u0051\u0067\u0073\u0035\u0067\u005a\u0040\u003f\u0020\u0043\u0040\u0036\u0067\u0076\u0046\u0066\u004b\u006b\u006c\u007b\u003e\u0068\u0044\u0038\u0062\u0055\u0020\u005f\u0026\u006e\u0059\u003b\u0048\u005d\u0030\u0062\u0033\u0052\u0042\u0057\u0034\u0050\u004d\u0058\u007a\u0048\u003a\u0036\u0075\u0040\u0026\u0042\u005f\u0067\u0068\u0040\u0079\u0051\u002c\u0075\u0059\u004a\u0038\u002a\u005f\u005b\u0070\u0027\u0072\u0051\u007e\u0027\u007b\u003f\u0036\u0065\u0064\u0041\u003d\u007c\u0049\u0040\u004b\u0078\u0070\u0072\u0070\u003e\u003c\u004b\u0074\u0022\u0027\u005f\u0051\u0077\u006f\u0058\u0039\u0055\u003d\u0051\u003c\u006f\u0022\u0044\u0059\u0079\u0067\u0026\u005d\u0040\u0027\u0052\u0048\u0035\u0051\u0033\u002a\u0038\u0020\u007a\u0033\u0051\u0024\u0070\u0052\u003c\u0060\u0067\u004f\u006f\u0042\u0036\u006d\u006a\u006c\u0073\u003a\u003c\u0072\u005d\u0069\u006d\u006a\u0046\u0055\u0057\u002c\u007c\u005d\u005a\u0072\u0054\u0034\u0069\u0025\u0028\u006e\u0077\u0047\u0065\u0024\u0069\u0042\u006d\u0049\u0072\u0029\u003c\u0041\u0035\u0030\u007b\u006a\u0034\u0044\u0029\u006d\u0055\u0047\u0072\u0028\u0065\u007b\u0021\u0055\u0021\u0035\u004f\u005a\u005c\u0069\u0033\u005e\u0076\u006c\u0059\u0033\u0041\u0051\u0023\u0071\u006f\u0023\u0069\u0064\u0046\u0064\u004b\u0069\u0039\u006b\u006a\u006f\u0036\u002c\u0024\u0029\u0045\u002e\u004c\u0043\u0031\u004e\u0047\u0020\u002d\u0027\u004f\u0040\u0068\u0074\u0027\u005e\u003c\u003b\u005f\u0033\u002c\u004c\u005d\u0033\u0034\u003d\u0070\u0035\u0023\u0074\u003f\u0046\u0043\u0073\u005e\u0077\u0028\u0059\u005f\u0044\u002b\u002b\u0045\u0055\u0020\u0020\u0064\u0061\u0048\u002f\u0022\u0030\u004d\u0069\u005b\u0022\u0074\u007c\u004a\u0076\u0067\u0020\u003b\u0076\u0040\u002d\u007e\u0073\u0028\u003f\u002f\u0077\u0042\u007c\u0021\u0046\u002d\u004a\u004c\u0044\u0060\u0078\u0077\u004f\u0036\u0039\u0059\u003d\u0059\u005c\u0051\u0022\u0063\u0039\u006d\u0057\u0062\u0062\u0051\u0056\u0026\u0062\u0040\u003f\u0041\u0044\u0034\u0062\u006a\u0043\u0046\u0039\u003f\u0042\u002d\u0046\u005d\u0073\u0024\u0045\u003c\u0021\u006c\u007d\u003e\u0074\u0032\u002f\u005f\u0067\u005b\u0038\u0030\u0075\u0032\u0062\u004e\u0036\u0029\u0066\u0032\u004b\u006b\u005f\u004b\u005e\u0021\u004f\u006e\u006d\u0075\u005f\u002e\u0071\u003a\u0074\u005c\u0048\u0070\u0062\u004c\u006f\u0047\u0065\u0047\u004c\u004b\u007c\u0025\u0055\u0051\u0072\u007a\u003c\u002d\u0064\u0042\u0042\u0043\u0067\u004c\u004a\u0027\u0033\u0052\u0032\u005c\u0045\u002d\u0054\u006e\u0056\u0073\u003b\u0054\u007e\u0024\u003d\u0042\u007a\u0077\u0061\u0061\u0029\u0050\u005f\u007b\u0049\u0033\u0023\u0067\u0038\u007d\u0047\u005c\u004a\u007e\u002e\u007d\u0077\u0029\u0062\u002a\u0043\u0043\u006d\u007b\u006f\u0056\u004d\u006c\u0061\u007c\u004a\u0030\u0036\u0047\u007b\u0036\u0078\u0077\u0064\u0020\u0050\u0049\u002f\u0035\u0034\u0072\u003a\u006d\u0068\u0030\u002f\u0047\u0021\u0048\u0063\u005b\u004d\u0037\u005a\u0026\u0072\u0070\u0079\u0060\u004c\u004b\u0061\u007c\u0027\u002a\u0036\u0074\u0059\u006b\u004d\u004b\u0047\u0052\u0068\u0054\u0056\u0044\u0044\u0063\u0051\u0074\u007e\u0054\u002c\u006b\u0025\u002f\u0037\u0075\u005c\u0054\u0046\u0038\u0050\u0053\u0044\u0027\u005b\u0079\u005c\u0065\u0035\u0051\u0061\u006e\u0024\u0025\u0037\u007c\u0033\u004b\u0053\u007c\u0046\u0026\u0040\u0045\u0051\u005c\u005e\u0022\u005d\u0034\u007c\u0065\u0038\u0068\u0079\u002f\u0020\u0068\u0037\u004a\u0058\u0060\u003c\u006f\u0062\u0050\u007b\u0057\u0026\u007c\u0071\u0078\u0073\u0071\u0039\u0062\u0054\u004c\u0058\u004e\u0050\u006b\u0027\u0057\u006c\u0040\u0027\u0061\u006f\u005c\u003d\u0033\u0028\u007c\u0076\u005c\u0067\u0022\u007c\u0021\u0064\u0055\u003a\u0031\u0029\u007d\u006a\u006a\u005e\u003b\u002c\u0067\u0044\u0021\u0057\u0047\u003b\u0062\u005f\u0044\u0056\u0030\u0025\u0044\u002f\u0025\u006c\u0075\u0058\u0031\u0029\u0056\u002a\u0054\u0054\u0036\u0036\u0036\u0062\u0073\u0025\u002c\u005a\u005b\u005c\u003a\u0078\u0026\u004e\u0021\u005e\u0064\u004a\u006f\u0050\u0032\u0078\u005f\u0049\u0070\u0064\u0030\u0070\u0030\u003e\u0033\u004e\u003c\u0054\u0077\u002c\u0028\u002c\u0069\u0030\u006a\u0079\u0029\u003d\u0027\u003f\u006d\u006d\u004b\u0079\u002b\u0030\u003e\u0064\u0029\u0051\u0036\u0064\u006b\u0072\u0040\u002a\u003e\u0040\u0071\u002e\u003e\u0025\u006f\u005b\u0029\u0063\u0050\u0073\u0048\u006a\u0060\u0042\u0065\u003e\u002f\u003e\u0076\u007c\u006c\u006b\u0057\u0021\u0033\u0033\u0036\u003c\u0072\u0022\u005e\u0030\u006f\u0055\u003c\u0034\u0054\u0023\u0055\u0036\u0058\u0027\u003a\u0038\u007e\u006b\u0028\u003f\u006a\u0026\u0042\u007c\u0024\u002f\u0025\u0056\u0072\u0030\u002e\u0035\u0051\u0038\u0067\u004f\u0064\u0068\u003c\u0027\u0056\u0049\u0065\u0057\u005e\u0021\u007a\u0060\u007a\u0065\u0025\u0051\u0041\u0070\u0020\u0063\u0070\u003c\u0060\u0066\u005f\u0067\u0071\u0046\u0071\u0058\u0034\u0069\u0036\u0026\u004e\u006f\u0020\u0065\u0069\u0030\u0045\u003d\u0040\u0029\u0062\u0077\u0050\u007b\u007d\u003c\u0062\u007d\u0050\u0035\u0027\u0020\u0062\u0037\u0025\u0032\u0051\u0044\u0050\u002c\u006f\u0063\u0036\u0069\u003b\u0048\u003f\u002e\u003a\u003b\u0066\u0041\u0046\u0036\u003e\u0066\u0054\u0045\u0022\u0030\u0032\u0042\u0028\u0052\u004a\u0062\u003b\u0028\u0051\u0078\u0040\u007c\u0062\u006e\u006e\u006a\u005b\u0066\u007c\u005c\u0072\u004b\u007a\u0026\u007d\u0030\u007e\u0079\u0029\u006b\u006c\u0058\u0041\u0032\u0073\u0079\u006c\u0062\u006b\u0036\u005d\u003a\u002e\u002b\u0054\u002f\u0051\u0031\u0033\u005c\u004c\u0028\u0036\u0070\u0070\u0047\u0040\u002b\u0072\u0074\u0043\u005e\u0020\u0033\u0035\u0075\u0058\u004c\u0044\u006c\u004f\u0058\u005f\u006f\u0050\u0070\u0042\u0070\u0052\u0057\u002a\u0047\u0037\u0038\u0075\u0048\u0040\u0061\u0025\u007e\u0021\u0074\u002c\u005d\u0035\u0029\u0034\u003c\u0076\u0075\u003e\u0059\u0064\u0077\u0025\u0079\u004a\u0042\u006a\u006d\u007e\u0034\u002d\u0057\u0025\u0073\u0054\u0040\u004a\u005a\u002f\u0024\u0066\u005b\u0028\u005a\u007e\u002a\u0032\u0060\u004d\u0023\u0067\u006f\u0044\u0029\u0079\u0056\u003c\u0055\u0074\u0029\u0070\u0060\u006b\u007d\u0060\u0059\u0055\u004e\u005b\u0044\u0069\u0045\u0069\u006f\u0075\u0031\u0060\u0056\u006b\u0055\u005c\u004c\u0051\u0061\u004c\u007c\u0047\u0078\u0071\u0079\u0038\u0051\u0065\u0069\u0021\u0029\u0048\u0077\u002c\u002c\u006b\u0079\u0045\u0079\u002a\u004d\u003c\u0029\u0069\u004a\u0025\u002f\u0030\u0057\u004f\u0078\u002b\u0049\u006a\u0070\u004b\u0052\u004e\u0056\u0036\u0071\u0050\u0042\u0059\u0070\u0071\u0063\u0073\u0060\u0032\u004b\u0061\u0041\u007b\u004f\u005b\u0055\u0025\u007c\u002c\u0077\u0032\u005e\u006e\u007e\u0020\u0039\u0035\u0034\u005a\u0063\u005b\u0034\u0072\u005a\u0062\u003b\u003e\u0063\u0070\u0078\u0028\u004b\u0038\u0068\u0058\u0040\u0036\u0057\u007a\u004b\u0040\u0079\u004a\u0069\u0061\u0057\u005c\u003f\u0072\u0053\u0033\u0072\u0059\u004b\u0049\u004b\u0032\u003c\u0039\u0036\u004c\u0067\u0034\u006f\u0073\u0022\u0048\u0032\u0030\u0047\u0068\u0079\u006a\u0056\u0063\u0045\u007d\u002b\u005b\u0063\u0055\u004e\u0069\u0027\u003f\u005e\u003a\u003f\u003c\u0065\u0035\u002b\u002e\u0021\u0064\u0024\u006e\u004b\u0035\u0077\u005f\u0023\u0071\u005a\u0029\u006a\u003c\u0047\u0077\u0048\u002d\u006f\u0031\u0054\u006e\u0036\u006d\u006a\u0068\u0064\u0043\u0073\u0046\u0022\u0048\u007a\u0026\u0023\u0027\u004f\u0067\u0066\u0078\u006a\u0038\u0023\u0055\u0030\u006f\u007b\u0067\u006b\u004a\u0056\u0037\u004d\u004e\u0073\u006f\u0062\u006b\u0023\u0065\u005a\u0024\u0041\u006f\u007e\u0073\u0050\u0048\u002b\u0026\u0050\u0079\u0076\u0043\u0022\u004b\u0031\u0025\u006a\u0024\u002e\u0076\u0067\u0020\u0077\u002b\u0038\u002d\u0046\u0055\u0030\u0036\u0035\u005f\u004b\u0074\u006e\u0023\u0076\u0030\u0026\u002c\u0024\u0071\u0023\u005a\u004c\u005d\u002b\u0055\u002f\u0059\u0043\u006d\u0064\u006d\u0063\u005b\u0050\u0063\u0051\u002c\u004a\u0063\u004f\u003b\u007e\u005b\u005e\u0061\u002b\u0031\u003c\u002d\u0056\u006f\u006f\u007c\u0042\u004b\u0045\u0045\u006f\u006c\u0036\u0021\u0046\u006a\u003e\u0076\u0055\u0077\u005d\u0038\u0068\u0047\u0042\u0054\u002b\u0024\u0058\u0067\u004a\u0071\u0079\u0061\u0037\u0025\u0053\u0029\u0023\u0066\u0070\u006e\u0070\u002e\u006a\u0042\u0037\u0039\u005b\u0070\u0066\u004e\u0028\u004d\u0038\u005e\u0079\u002f\u0068\u007b\u004d\u0032\u0052\u0073\u0025\u003c\u005d\u0023\u0068\u005f\u0076\u003d\u0050\u0056\u0056\u0074\u002f\u0039\u0064\u006b\u0060\u0030\u0035\u0027\u006c\u0064\u0024\u0043\u0034\u0079\u004f\u005b\u005e\u003b\u0059\u0071\u0038\u0066\u0041\u0028\u0059\u0050\u0062\u0074\u0052\u0041\u0046\u0045\u006b\u002c\u006f\u002c\u0056\u0076\u0050\u004c\u005d\u0051\u0028\u0047\u0038\u0045\u0030\u0038\u0028\u002c\u0042\u006e\u0022\u0077\u004c\u0057\u006a\u0052\u0020\u0073\u0024\u0072\u007b\u0063\u0072\u005b\u003b\u0050\u004a\u0054\u0061\u002d\u0076\u0038\u0057\u002c\u0034\u006b\u003c\u003f\u002e\u003c\u0063\u0051\u004c\u002f\u0045\u0048\u0042\u0065\u0063\u005b\u0065\u0058\u0049\u004b\u0055\u0045\u005f\u0075\u0030\u002d\u0031\u0048\u005d\u005f\u0053\u0060\u0053\u002c\u0036\u0079\u0048\u005a\u0074\u0056\u0078\u0034\u0022\u0077\u0076\u0031\u0061\u007c\u002c\u0021\u0023\u002d\u0060\u0055\u006e\u002e\u004a\u004d\u0032\u0054\u0060\u004d\u0062\u0047\u0056\u005f\u0074\u006b\u0031\u0077\u005d\u006e\u006f\u0025\u0055\u005f\u007b\u0025\u0054\u0048\u003c\u007e\u007d\u006e\u0071\u0043\u0040\u002d\u0032\u005c\u003e\u0048\u0030\u003f\u0072\u002a\u005c\u0045\u0023\u0052\u005c\u003e\u004a\u0021\u0067\u003d\u005c\u006d\u0021\u0028\u002e\u0069\u0043\u002e\u0079\u0020\u0061\u003e\u0041\u0039\u0041\u0036\u0045\u0029\u0074\u0045\u006c\u006e\u004d\u003a\u0035\u005e\u002b\u007d\u002d\u005b\u004b\u0065\u0036\u005a\u0049\u0022\u002f\u0061\u003c\u005a\u0032\u003e\u002a\u004c\u0054\u0045\u0038\u0025\u006e\u0025\u0070\u005e\u006b\u003a\u003e\u002f\u005c\u0053\u0024\u002e\u006f\u0028\u006e\u005c\u0028\u002e\u0074\u0060\u005e\u0062\u0060\u0040\u0021\u0067\u0039\u005d\u0061\u003f\u0056\u0034\u0023\u0055\u0037\u0051\u0077\u003e\u0066\u002d\u0053\u0073\u005a\u0038\u002a\u006f\u002a\u003c\u0023\u0034\u0056\u0048\u0067\u004e\u0036\u0079\u005e\u0028\u0024\u006f\u0047\u003b\u0062\u006e\u002b\u0023\u004f\u0068\u005a\u0030\u0047\u0025\u0028\u0070\u0062\u004a\u004c\u0026\u007c\u0041\u0065\u0035\u005c\u0024\u0073\u007d\u0057\u004f\u006c\u003e\u0049\u0026\u007e\u0079\u0040\u002f\u004a\u004f\u005b\u0056\u0025\u005f\u005e\u007d\u0037\u004c\u0028\u007d\u0061\u0038\u004a\u0038\u002a\u007e\u007c\u007b\u0035\u0043\u005c\u003c\u006b\u0026\u005d\u006a\u0050\u002f\u0066\u006c\u002d\u0044\u0030\u0046\u0046\u0036\u0030\u0061\u0078\u0061\u002f\u0050\u0074\u0046\u0055\u0032\u002e\u002d\u0052\u0037\u002d\u0029\u0033\u0067\u002b\u0047\u0065\u0058\u0051\u0074\u0050\u0026\u006e\u0071\u0050\u0075\u0068\u0052\u007d\u0078\u006d\u0038\u002a\u006c\u0040\u004c\u0041\u004c\u005e\u0073\u003d\u0070\u006e\u003d\u0020\u005c\u0021\u0057\u0032\u004f\u006a\u0055\u002d\u0048\u0076\u0052\u0060\u006a\u0068\u0079\u006c\u0045\u0052\u003f\u0030\u0025\u0073\u0052\u006a\u006b\u005f\u0059\u0024\u002b\u0036\u0022\u0034\u0036\u0038\u0035\u002a\u003e\u007d\u0037\u0050\u005b\u0033\u0066\u0068\u002a\u005b\u0035\u0075\u004a\u004a\u0035\u0035\u0049\u003f\u003a\u006e\u003e\u003a\u004e\u005c\u002e\u006d\u0076\u003e\u0037\u0069\u0053\u0067\u002c\u0021\u005e\u003f\u0060\u002d\u0063\u0044\u006a\u002c\u0055\u0030\u004e\u007e\u0077\u0046\u004d\u0035\u0079\u003b\u0056\u004a\u0046\u0046\u004b\u005c\u0023\u0027\u006b\u0031\u004a\u004f\u006a\u005f\u0030\u0074\u0076\u0037\u0069\u0054\u004e\u007c\u006a\u006a\u0037\u0047\u004a\u0039\u0079\u002f\u004b\u0034\u0060\u004d\u0056\u0033\u002c\u0052\u007c\u0040\u0033\u005f\u006a\u0053\u0049\u007e\u003d\u003d\u002e\u0057\u003f\u0035\u004c\u006b\u005b\u0047\u002c\u0073\u003e\u007e\u0072\u006e\u002e\u0067\u004b\u0042\u006d\u007e\u0061\u0030\u0021\u0021\u0049\u0031\u0039\u0034\u002f\u0074\u0042\u0054\u0053\u007b\u004f\u002a\u0032\u0073\u0049\u0035\u006c\u0020\u0044\u003e\u0063\u0054\u003d\u006c\u002c\u0057\u003e\u0073\u0028\u0025\u005c\u0043\u005b\u0039\u0037\u004a\u0066\u0054\u0074\u0065\u004c\u0051\u006a\u002b\u0079\u0050\u007e\u002d\u0059\u006f\u005a\u002c\u0051\u0060\u0042\u0042\u0070\u0053\u0043\u006c\u0077\u003e\u002c\u0027\u0056\u0027\u0056\u0064\u0027\u0067\u0049\u003e\u0061\u0059\u0025\u0071\u0032\u002d\u002f\u006f\u0075\u003b\u003b\u0071\u0050\u0037\u0072\u0064\u005b\u0055\u0040\u007e\u0048\u0044\u0070\u004b\u0047\u0048\u0021\u0075\u003d\u005f\u003c\u006f\u0057\u0057\u005a\u0048\u0049\u0074\u0052\u007e\u0054\u0045\u003f\u0042\u0079\u0075\u0061\u0068\u004f\u004d\u0043\u0029\u0057\u0036\u0078\u003b\u0063\u003e\u005d\u0066\u0026\u0056\u0071\u0024\u005a\u002e\u0039\u0024\u005f\u0067\u004c\u0061\u0049\u003d\u003f\u0073\u004d\u0056\u0046\u005c\u002d\u0046\u0068\u0024\u0070\u0048\u006d\u0050\u007d\u0038\u006d\u0052\u0045\u003b\u006d\u0078\u005d\u003b\u007c\u0069\u0068\u003d\u004e\u0051\u0054\u0033\u0078\u003f\u0074\u005e\u002d\u0066\u0046\u004f\u0076\u002e\u003e\u006f\u0044\u005d\u0028\u0036\u0041\u0030\u0036\u004c\u004c\u007c\u0052\u007c\u0065\u0069\u0025\u0039\u0074\u003d\u004a\u0056\u0024\u0022\u0038\u0032\u003f\u002a\u0062\u0065\u0063\u0044\u004f\u0065\u0077\u005e\u007e\u005e\u002b\u0023\u005c\u0049\u0069\u003a\u0059\u006d\u003a\u0045\u0046\u0021\u0063\u007b\u0057\u003e\u005d\u0047\u003c\u0041\u0029\u0045\u0037\u0077\u0035\u0029\u0057\u005a\u0027\u0074\u0078\u0049\u007c\u0063\u005f\u0055\u005c\u006d\u0075\u005a\u0070\u0053\u004b\u002e\u004b\u0051\u0057\u0040\u0048\u0038\u0079\u0072\u0031\u0068\u0040\u007a\u007a\u0037\u004c\u0064\u0024\u0033\u0042\u0045\u0060\u0039\u0040\u004e\u0052\u0061\u0023\u0040\u007d\u0028\u0062\u006a\u004f\u007a\u005e\u0034\u0075\u0073\u0071\u0064\u0068\u0036\u0020\u0059\u005c\u005a\u004b\u0034\u0078\u003f\u002d\u0047\u0061\u0044\u005e\u0036\u0038\u005d\u0035\u0073\u006e\u0048\u0027\u0032\u005c\u0073\u0023\u0028\u0065\u0048\u0033\u0034\u0069\u0077\u0079\u0036\u0033\u0021\u0077\u003f\u004b\u006b\u006e\u004f\u006d\u0061\u005c\u0038\u007c\u0057\u005e\u0035\u005f\u0029\u003a\u004a\u006b\u004e\u0032\u005d\u007e\u0046\u0072\u005b\u0078\u0075\u0027\u0069\u006f\u0050\u007a\u0034\u003c\u003b\u0077\u0036\u0051\u004a\u0022\u0020\u0020\u0034\u003b\u0070\u0026\u0059\u007a\u0049\u0071\u002a\u0063\u0046\u0037\u006d\u007e\u0024\u002f\u0061\u0071\u0050\u0074\u0057\u006f\u0064\u0032\u0065\u0061\u003f\u0071\u0022\u0067\u0075\u0031\u0027\u0053\u0060\u0029\u002c\u002d\u003c\u0048\u0066\u0039\u0043\u007e\u006d\u003e\u0061\u0062\u0049\u003e\u0060\u0071\u0075\u006e\u006a\u0054\u003b\u0072\u0070\u0035\u006f\u0040\u003a\u0043\u006f\u007b\u0041\u003c\u005a\u006b\u0030\u0053\u006a\u002e\u0020\u0076\u0054\u0043\u0044\u0063\u002b\u0036\u0078\u0070\u003d\u0052\u005b\u0065\u0079\u0031\u005a\u0073\u0043\u0059\u002d\u002f\u0065\u0051\u007e\u0060\u004d\u0023\u0042\u0049\u0076\u0037\u0040\u003b\u0036\u003d\u007b\u0067\u0033\u0046\u0040\u002a\u004c\u0075\u0037\u006f\u0057\u003c\u006c\u0067\u0071\u007a\u002e\u004d\u0033\u0068\u002b\u0046\u004f\u0020\u0020\u004f\u0042\u0030\u0032\u004e\u007a\u006f\u0068\u004e\u0049\u005c\u004c\u007d\u0045\u0027\u0064\u002a\u0063\u0044\u002a\u003d\u0063\u0052\u004d\u0030\u0057\u0034\u0036\u003f\u003f\u0077\u0036\u005d\u0065\u0066\u0059\u005e\u0026\u004d\u005c\u006a\u0051\u007b\u002a\u0039\u002c\u0020\u0051\u0070\u004f\u0031\u0074\u0076\u0027\u006c\u0065\u0046\u0064\u003b\u004b\u0047\u007c\u0042\u0032\u0059\u005a\u0046\u002b\u0043\u0037\u0055\u0064\u0050\u0021\u002e\u0058\u0067\u0064\u0039\u0023\u005d\u0024\u003d\u0073\u0078\u0023\u004b\u005e\u0064\u0031\u003b\u006f\u005c\u003e\u0039\u002b\u006f\u0045\u0027\u0064\u0066\u004f\u0026\u005c\u0043\u0061\u0022\u004f\u0046\u0025\u0020\u002b\u004f\u0046\u005f\u0064\u0079\u007b\u006f\u0026\u004b\u007c\u0036\u002b\u0076\u0054\u004a\u006b\u0041\u0025\u0072\u0053\u0057\u003b\u002d\u0062\u002d\u0022\u003b\u0069\u0067\u0070\u003b\u0044\u007d\u006a\u0062\u002f\u002c\u004d\u0073\u0067\u0039\u002f\u0077\u0065\u007e\u002a\u0052\u003e\u0030\u0028\u0079\u0047\u0062\u0078\u007a\u0044\u0079\u003b\u0060\u0045\u0072\u0076\u0049\u0054\u0023\u006d\u0022\u007a\u003d\u004e\u0069\u006a\u004e\u0066\u0049\u006f\u0028\u003c\u002f\u0041\u004f\u0056\u0067\u0066\u0047\u0026\u002b\u002a\u0069\u0031\u0035\u005e\u0064\u0046\u0031\u007a\u0027\u007e\u004b\u0023\u0039\u005d\u002f\u005e\u0067\u0068\u0061\u0060\u0062\u0059\u0066\u0072\u0047\u0060\u0040\u0020\u0047\u0043\u002c\u0037\u0039\u0038\u006c\u0024\u0055\u0030\u006a\u0036\u007e\u005f\u003d\u005b\u006a\u0048\u004c\u004a\u0030\u006c\u0064\u0023\u0034\u0068\u0057\u0068\u0054\u007d\u0075\u0031\u0071\u0043\u0022\u0046\u005d\u0025\u0030\u003f\u0067\u0029\u0037\u0020\u0060\u0060\u0057\u0074\u007d\u0031\u0027\u0044\u0062\u0063\u0023\u0063\u0061\u0046\u0058\u007c\u004b\u0029\u0065\u005c\u0055\u0029\u0055\u0064\u0032\u007d\u0074\u0042\u0066\u007e\u007d\u003e\u005a\u0027\u0039\u0032\u0078\u0053\u0046\u0052\u0079\u0021\u007c\u0029\u002f\u006f\u002a\u0043\u0063\u002f\u0066\u0073\u007a\u002f\u004b\u0050\u0046\u0065\u005d\u005d\u002e\u0047\u007c\u006c\u0038\u0070\u0075\u0034\u0057\u0058\u002d\u005b\u006b\u0036\u0058\u002a\u006a\u003b\u007c\u0022\u0063\u0049\u0045\u0022\u0021\u0038\u0023\u003d\u0064\u003a\u0032\u003e\u002e\u0020\u0021\u0073\u0070\u0059\u0078\u0040\u007d\u0050\u005b\u0026\u006d\u005f\u005f\u007a\u0049\u006d\u002c\u0029\u0067\u007d\u002a\u007a\u005c\u007a\u0074\u0063\u0056\u005a\u006e\u0030\u0033\u004c\u0042\u002e\u005b\u0025\u0063\u002b\u002a\u0078\u006e\u0053\u0051\u007a\u0022\u006c\u002f\u0022\u0034\u0076\u0046\u0074\u0073\u004f\u0044\u007d\u005b\u003b\u0055\u0059\u0068\u0039\u0033\u007a\u002b\u0072\u002c\u007c\u0071\u0052\u004a\u0030\u0034\u005b\u0043\u0077\u003a\u003b\u005b\u0023\u005a\u005d\u0062\u0060\u0034\u005e\u002c\u002b\u0047\u0036\u007a\u0036\u0054\u004e\u0068\u003b\u006f\u0033\u006c\u002f\u0037\u005a\u0062\u006a\u0049\u0048\u0034\u0052\u003b\u005a\u0042\u004c\u0073\u007d\u002c\u0053\u002c\u0060\u0064\u006a\u005c\u0064\u0077\u0055\u0079\u0054\u0042\u007e\u0032\u0076\u004e\u0068\u003a\u0032\u0027\u0078\u0060\u0021\u005b\u0063\u004c\u0072\u0029\u0061\u0037\u0036\u005a\u0079\u0035\u002d\u0068\u006e\u0072\u003b\u0075\u0054\u0077\u0073\u005b\u0062\u003b\u005d\u0073\u0029\u002a\u006c\u0058\u0030\u0064\u0061\u0024\u0042\u0049\u0023\u002c\u0024\u0035\u003c\u0052\u0043\u002e\u0054\u007e\u0068\u007a\u0056\u003a\u0079\u0076\u0042\u0063\u0033\u0024\u0046\u0039\u002d\u0035\u0037\u004f\u0078\u0066\u005a\u0036\u0028\u002c\u005a\u0060\u006f\u0028\u0068\u0072\u003a\u0027\u0037\u0046\u0032\u005a\u0063\u0076\u0076\u0040\u005f\u0054\u0046\u0025\u002c\u0075\u0026\u0079\u0050\u0047\u005a\u002e\u0029\u0026\u002e\u0075\u003d\u0048\u004c\u0062\u0058\u006d\u002f\u0056\u0058\u0071\u0049\u0051\u0051\u0050\u005b\u0073\u005c\u007d\u0062\u003c\u0025\u0041\u0062\u007d\u0029\u0020\u003b\u005c\u0052\u0053\u002c\u0074\u007c\u0057\u006f\u0072\u004a\u0039\u0041\u0057\u0040\u007b\u004b\u0068\u002e\u0078\u0027\u0056\u0047\u0079\u003c\u002b\u0032\u0077\u004a\u007d\u0067\u0028\u0044\u0059\u0023\u0046\u0076\u0044\u006f\u0069\u0042\u0064\u0025\u002c\u006b\u003c\u007d\u0037\u002e\u002a\u0059\u004f\u0027\u0036\u0036\u004c\u0030\u003b\u005e\u0030\u0053\u0074\u0033\u006e\u0050\u0049\u0077\u002b\u0064\u003e\u004f\u0067\u007b\u005f\u004d\u0026\u007b\u003f\u0051\u002b\u0028\u0031\u003f\u0055\u0047\u0027\u005a\u0062\u0046\u0060\u0068\u004b\u0039\u007e\u0028\u005d\u006d\u0038\u006c\u007e\u0029\u0047\u0062\u0037\u0039\u0068\u0049\u007c\u0043\u0050\u0055\u006c\u0069\u0022\u003b\u0068\u0024\u0061\u003f\u003f\u0052\u005e\u0057\u005d\u003d\u0051\u0063\u0045\u0075\u0044\u0022\u0035\u0029\u004b\u004e\u0056\u0057\u007b\u0032\u004f\u006a\u0047\u002c\u0064\u0029\u003e\u0057\u0062\u0065\u0049\u0056\u0039\u0028\u0021\u0074\u004c\u004c\u0030\u0048\u0038\u0030\u003b\u005a\u002d\u005d\u0039\u0038\u0035\u0022\u002f\u0051\u005e\u005e\u0076\u0033\u0031\u0058\u0059\u0054\u002e\u004c\u0074\u006a\u007c\u0073\u002c\u0062\u0078\u004d\u007a\u0049\u0063\u0060\u0079\u0042\u0028\u0051\u003f\u0050\u0053\u0059\u0034\u004d\u0076\u002f\u0049\u0052\u003e\u0043\u007b\u0068\u002c\u0059\u0041\u0044\u0035\u007c\u0070\u0042\u0029\u0037\u004f\u0045\u0043\u0061\u006c\u006c\u0078\u0022\u0064\u005b\u0032\u006e\u0024\u006c\u003c\u0062\u006d\u0030\u006b\u0058\u004f\u0030\u0076\u006f\u0047\u003c\u0079\u0053\u0028\u0028\u0024\u0047\u003a\u0061\u005a\u004d\u0066\u0027\u0043\u007c\u003d\u005f\u0023\u004d\u0044\u006c\u002d\u0034\u0041\u0051\u0036\u002b\u005f\u0078\u007e\u0053\u0049\u0025\u0021\u004d\u007d\u0071\u0038\u004c\u0048\u006c\u003f\u0021\u005c\u0057\u0024\u0026\u004c\u0069\u006d\u0043\u0048\u0079\u0056\u0034\u003a\u0050\u0076\u0032\u003a\u0061\u003b\u0069\u0024\u0048\u0073\u0052\u006d\u0020\u0055\u0041\u0048\u0059\u0046\u004a\u004d\u002f\u0075\u0064\u0077\u0047\u0069\u0049\u006f\u002a\u0069\u0046\u007e\u002d\u004d\u006c\u0051\u005a\u0020\u004c\u0028\u005b\u005d\u0021\u0059\u0051\u0020\u0022\u0074\u0072\u0020\u003d\u005b\u0056\u004d\u0077\u0049\u0071\u002c\u003b\u0078\u0075\u0060\u007a\u006e\u0066\u0028\u0044\u0061\u0069\u0025\u0065\u0049\u0045\u004b\u007d\u0030\u0037\u0073\u006e\u005c\u0071\u002f\u005e\u0074\u003a\u0070\u0057\u0039\u0030\u0026\u0021\u0072\u0073\u0069\u005c\u0066\u0079\u0073\u0069\u0036\u0020\u0040\u005a\u0069\u006b\u0044\u0074\u0067\u0072\u0025\u003d\u0053\u0036\u0075\u0070\u0051\u0058\u004f\u004b\u005f\u007d\u005b\u0074\u0024\u0078\u007c\u0020\u005d\u0066\u003a\u0044\u0062\u004d\u0053\u002f\u0068\u0045\u005b\u005d\u007a\u0045\u0024\u0072\u0027\u0060\u0020\u007c\u0058\u0061\u0072\u0050\u006e\u002f\u0066\u004a\u0075\u0055\u0059\u0028\u007d\u0067\u004f\u0068\u006e\u0034\u002e\u0069\u007b\u0045\u0052\u0045\u0073\u003a\u0065\u0024\u004e\u0070\u0063\u006e\u002f\u003f\u003e\u0027\u0069\u004b\u004d\u0058\u0043\u0053\u003d\u007a\u0029\u0027\u0047\u0044\u0024\u005f\u0064\u0029\u002c\u0055\u006d\u0025\u0045\u0031\u0028\u003b\u007b\u0039\u006f\u002a\u006f\u006f\u0044\u0059\u0059\u005f\u0055\u006c\u0049\u004a\u0035\u006e\u0042\u003d\u003c\u0063\u002a\u007a\u0078\u0041\u0050\u002f\u004e\u0077\u0023\u003a\u0072\u005d\u0038\u0053\u006b\u0022\u0062\u0034\u0040\u0076\u004e\u006c\u0029\u002b\u004a\u0077\u0066\u0066\u0072\u007c\u0079\u0072\u0055\u0046\u0022\u0027\u0071\u0060\u0052\u0058\u0078\u0076\u002b\u003a\u005c\u0047\u003d\u004c\u0035\u0066\u0051\u006a\u004c\u0062\u006e\u0061\u0044\u006b\u002e\u0056\u0072\u006f\u0027\u0053\u0030\u004b\u0079\u003b\u0051\u0060\u0077\u004d\u0048\u0053\u0054\u005c\u005a\u007e\u002d\u0071\u0032\u0030\u0077\u007c\u0045\u0044\u0051\u006f\u0079\u0027\u0045\u0023\u0041\u0025\u007d\u005b\u0067\u0043\u0064\u0034\u0046\u0030\u005d\u004d\u004f\u0032\u005a\u0029\u0051\u002f\u0036\u006d\u005d\u0072\u0037\u003d\u0066\u0047\u0040\u004b\u004f\u005d\u0055\u003d\u0033\u0067\u0025\u0020\u0051\u004f\u006b\u0023\u0065\u0066\u0074\u0074\u0026\u007a\u0052\u0046\u002f\u007d\u0047\u0077\u0044\u0050\u0061\u0038\u0044\u0060\u003d\u0032\u0078\u0061\u0034\u0044\u004b\u004a\u0032\u004b\u004a\u004d\u0065\u007a\u007d\u0027\u004b\u0050\u0057\u006b\u0058\u004d\u0076\u0038\u0065\u0038\u0053\u0030\u004b\u0056\u004b\u0056\u0074\u0030\u002c\u0070\u0060\u0042\u005d\u0048\u0054\u0075\u0033\u0074\u0045\u0071\u007b\u0028\u003c\u002d\u0053\u002e\u002a\u004b\u0070\u004c\u003f\u003f\u002f\u0030\u0034\u0050\u0039\u003e\u006a\u0039\u0022\u0026\u0072\u0026\u0050\u006a\u0058\u007b\u006f\u003d\u0070\u0029\u0065\u005d\u006a\u005a\u002b\u007e\u0039\u0052\u0061\u006c\u0035\u0058\u002e\u007a\u007d\u004c\u0079\u0042\u0039\u005c\u0047\u0071\u0041\u002d\u0042\u0031\u003b\u0074\u0065\u0059\u0076\u0071\u0078\u0033\u0021\u002b\u0024\u007b\u005e\u0055\u0056\u007a\u0036\u0072\u007a\u0031\u0079\u005a\u0061\u004a\u006e\u002b\u0072\u005b\u0079\u0047\u0056\u0075\u003e\u0079\u0059\u0073\u0078\u004e\u0075\u0057\u0055\u004f\u0054\u0076\u005e\u007c\u0067\u007b\u002b\u0051\u0045\u0040\u0040\u0052\u0061\u002c\u0037\u004e\u002b\u0055\u0036\u0037\u0060\u0023\u004f\u0055\u0042\u0031\u0073\u0052\u0048\u003f\u005a\u006a\u0057\u0037\u0044\u004f\u0031\u0030\u005f\u005e\u002e\u0061\u005b\u0038\u0055\u0022\u002b\u0059\u002f\u004c\u0069\u003d\u0046\u0039\u0078\u0055\u0070\u0040\u0034\u0068\u0078\u007e\u0076\u0026\u004f\u007a\u0042\u0034\u005f\u0054\u0029\u007b\u0050\u0038\u003a\u002f\u0054\u0038\u0023\u002c\u004a\u0052\u0037\u0023\u002d\u0063\u003e\u0066\u0027\u0051\u0043\u0027\u0053\u0058\u0079\u0029\u003e\u004f\u004f\u0048\u0063\u002d\u0025\u007d\u0056\u007a\u0027\u0054\u003c\u0064\u003b\u005a\u0060\u006d\u0056\u004d\u0072\u0045\u002a\u0040\u0028\u0028\u0070\u0052\u005c\u0027\u003c\u0049\u0063\u0051\u0045\u002f\u007b\u007b\u0021\u004c\u0042\u0039\u0038\u003b\u007a\u0046\u0024\u002e\u0051\u0062\u0020\u0065\u0069\u0074\u004d\u0077\u003d\u0076\u005e\u0053\u0046\u007e\u0076\u004b\u0050\u003a\u0077\u004f\u0041\u005f\u002e\u0051\u0057\u0059\u0079\u0061\u003e\u0061\u0022\u003e\u0076\u005b\u0050\u0059\u0035\u006c\u0039\u0064\u0065\u0035\u0059\u005f\u0033\u0055\u005f\u0049\u0072\u004d\u007c\u0067\u0036\u0037\u0069\u0036\u0043\u0064\u0030\u005e\u0049\u0060\u0032\u0032\u004b\u0020\u006b\u0025\u003f\u0047\u0031\u0047\u0029\u0040\u0042\u0032\u002b\u006b\u0054\u005a\u0034\u002d\u0039\u0041\u0076\u003d\u0028\u002f\u0025\u0034\u0053\u0054\u004d\u003c\u0054\u0025\u002a\u007c\u002c\u004d\u0024\u0034\u005c\u004f\u0064\u004a\u0072\u005b\u006e\u005b\u0070\u0025\u0063\u0042\u006d\u0070\u0058\u0035\u004a\u006c\u0062\u002a\u002e\u005d\u002f\u005a\u0061\u0024\u006f\u0050\u0058\u004d\u0063\u0078\u0029\u0056\u0079\u0061\u0060\u003f\u004a\u004b\u0021\u0054\u0044\u0041\u003b\u0046\u004b\u004e\u0033\u0020\u003f\u0045\u0057\u003e\u0032\u0055\u004d\u0045\u0074\u0054\u007d\u0053\u007a\u003a\u0074\u002e\u0078\u0066\u0032\u0075\u0057\u0047\u0058\u004a\u0064\u0032\u0029\u006c\u0039\u0065\u006a\u0023\u004e\u0048\u006d\u0041\u0073\u0035\u005f\u007e\u007d\u0069\u0037\u0027\u006f\u003b\u0053\u0030\u0042\u007d\u0053\u0052\u005f\u006b\u0072\u0060\u003c\u0032\u0067\u0058\u0077\u005b\u0039\u0022\u0069\u0063\u0047\u0056\u0068\u002b\u002b\u0023\u006c\u006a\u0070\u0077\u0022\u006a\u004f\u0065\u0038\u007e\u0050\u007e\u0032\u003b\u0037\u007a\u0040\u006c\u0050\u004c\u002c\u0023\u0077\u004b\u003e\u004e\u0036\u0073\u0022\u005c\u005d\u0040\u0042\u0073\u0041\u0051\u0060\u003b\u0074\u0070\u0071\u0033\u0061\u002b\u004c\u004c\u0036\u0075\u0078\u0035\u003b\u0040\u0044\u0079\u003b\u0062\u0079\u002a\u002d\u0055\u005c\u002b\u003a\u0050\u005e\u003a\u0049\u0062\u0052\u003c\u002b\u0055\u002c\u0064\u0067\u0075\u003f\u0024\u003e\u0071\u004a\u004c\u007d\u006b\u006e\u006d\u006b\u0079\u004f\u0070\u006d\u005c\u002e\u0025\u005d\u0032\u0078\u0051\u0048\u0073\u0058\u0072\u0020\u0035\u0043\u003a\u006b\u0077\u002a\u002b\u0030\u0029\u002a\u0026\u0060\u0079\u004e\u003a\u0020\u002a\u005d\u0046\u006b\u003a\u0028\u003d\u0026\u0075\u003b\u0028\u0053\u0042\u0035\u0056\u005e\u0052\u006c\u0066\u0059\u0049\u007a\u002e\u002c\u0037\u0052\u004b\u0053\u0052\u0069\u0044\u002d\u0041\u0073\u0044\u0068\u0044\u0039\u0074\u0044\u0027\u007c\u004e\u0036\u0037\u0071\u0030\u002b\u0049\u0021\u0046\u0068\u004b\u0059\u007b\u005a\u0037\u006e\u006a\u007c\u0035\u002c\u0037\u0049\u0021\u0047\u0051\u0054\u0035\u0067\u006a\u005f\u005c\u0054\u0060\u0031\u0075\u0074\u0049\u005c\u005d\u0060\u005e\u0031\u0022\u0060\u003e\u006e\u0061\u0061\u0031\u0071\u006f\u0076\u0046\u006e\u0046\u0077\u0072\u0031\u0043\u0034\u0037\u0077\u004a\u004c\u0054\u005e\u0055\u0069\u0020\u006b\u002e\u007e\u0075\u0046\u002a\u0079\u0022\u006a\u0050\u0070\u006b\u007c\u0026\u005c\u0039\u0020\u0033\u004f\u0023\u0024\u0058\u005b\u0073\u006e\u0024\u0057\u0027\u002c\u0076\u0077\u002c\u0074\u0030\u0026\u004b\u0038\u007d\u0060\u0069\u0026\u002c\u0076\u0028\u005e\u0028\u0046\u0049\u0060\u002c\u0036\u006d\u0067\u0028\u0059\u0055\u0054\u004e\u002a\u0066\u007c\u0061\u0076\u006e\u002b\u007e\u003a\u0055\u004a\u006b\u0040\u0062\u002b\u003b\u0066\u0022\u002b\u0060\u005b\u0036\u0027\u002c\u005f\u0054\u0035\u004b\u002a\u0075\u0067\u0040\u0040\u0037\u0043\u0067\u005a\u0076\u005f\u0073\u0067\u0070\u0073\u0028\u0035\u0052\u0062\u0049\u006a\u0043\u0035\u0037\u0035\u007d\u0020\u003d\u0024\u0060\u002d\u005e\u005c\u0064\u002b\u002d\u002a\u005c\u0050\u0055\u0054\u005e\u0073\u003a\u002e\u0037\u0064\u005f\u0048\u0063\u0052\u0045\u0039\u003c\u0070\u0021\u006f\u005f\u0069\u0055\u002c\u0050\u0020\u0028\u0028\u0072\u002e\u0064\u0029\u0078\u0034\u0023\u0035\u0030\u0066\u0028\u002e\u0027\u004d\u006f\u002a\u004e\u0040\u0063\u003f\u004a\u007e\u0049\u0074\u004b\u0041\u0066\u0054\u006a\u0028\u0037\u0035\u0054\u0038\u004d\u003b\u0041\u002d\u0076\u0057\u003c\u0054\u0035\u006b\u0061\u0020\u0031\u005e\u002e\u0071\u006a\u006f\u0030\u0043\u006c\u0063\u0047\u004b\u005d\u006f\u0047\u0032\u002a\u0052\u005f\u0037\u002a\u0073\u0045\u0021\u002c\u0049\u0062\u0021\u0057\u0051\u0056\u007b\u004f\u004c\u007c\u0040\u0042\u0041\u003a\u002e\u006b\u0024\u003b\u004c\u0051\u0030\u0047\u0079\u002c\u002d\u0045\u0074\u0071\u0052\u005c\u007b\u006d\u0039\u0037\u0063\u002e\u0054\u003a\u005f\u0066\u003d\u004b\u0063\u006e\u0049\u0024\u0073\u0061\u0071\u0050\u006e\u006f\u0041\u005c\u004f\u006c\u0049\u0074\u002a\u006f\u0020\u0076\u0078\u006e\u0044\u0055\u0055\u002b\u0072\u0053\u0041\u0057\u003d\u0032\u002e\u007d\u002d\u0045\u0025\u0072\u004f\u0027\u0026\u006a\u003f\u0031\u002d\u0050\u0025\u0059\u007d\u0035\u0042\u0048\u006d\u007e\u0074\u0036\u0037\u0070\u0077\u0030\u004f\u004e\u005e\u0045\u002a\u0041\u007a\u0035\u003f\u0060\u0049\u003b\u0063\u0048\u005f\u003f\u0077\u0059\u0042\u0054\u006e\u005e\u003b\u006c\u0078\u0074\u0067\u006b\u002e\u0052\u004f\u003e\u004a\u0020\u0061\u006b\u002c\u0059\u0067\u0046\u0051\u006d\u0077\u0062\u0049\u0062\u0031\u006a\u0032\u0043\u0060\u0034\u0065\u0033\u0066\u004d\u0028\u0044\u0054\u004b\u0056\u0056\u0070\u0070\u005c\u0041\u005e\u005d\u006f\u0063\u003f\u0054\u0034\u007b\u0032\u0051\u003e\u0058\u006f\u006f\u0070\u0028\u0079\u0064\u0020\u0020\u002e\u0063\u003d\u0031\u0038\u002c\u0020\u007b\u0076\u0059\u0035\u0021\u0023\u005b\u0041\u0072\u0070\u0073\u007e\u0021\u004b\u0048\u0062\u0044\u0053\u0058\u003f\u0047\u005a\u0054\u0029\u0042\u0031\u0021\u0041\u004b\u0028\u007b\u003a\u002f\u0031\u0057\u0047\u004b\u0031\u002d\u002b\u0028\u0078\u0054\u0056\u004d\u0026\u006f\u003a\u007a\u0026\u002a\u0071\u0062\u004a\u0020\u003d\u0061\u0021\u0047\u007a\u0072\u0023\u0067\u0046\u0043\u0062\u0037\u0061\u002a\u002c\u0078\u0045\u0034\u005f\u0063\u0067\u005a\u0024\u0045\u0066\u002c\u002a\u0038\u0079\u0062\u003c\u006c\u0068\u005d\u0021\u002f\u0020\u002c\u0022\u0077\u007d\u0068\u0055\u0073\u0027\u0048\u0033\u004c\u007d\u002a\u003a\u0059\u0040\u0064\u0035\u0048\u0065\u0059\u0033\u005f\u0046\u0062\u003a\u0050\u005a\u0024\u0067\u007b\u0034\u0049\u0079\u0073\u006b\u005d\u003f\u0060\u0062\u004a\u006e\u0068\u0039\u005e\u0042\u0046\u002d\u0043\u0027\u003f\u0057\u0065\u006b\u002d\u005e\u005c\u007a\u0077\u006b\u0021\u0053\u0065\u0035\u006c\u0022\u002c\u0042\u0029\u002a\u0056\u0074\u0030\u007d\u0065\u0071\u0068\u004e\u0077\u005e\u004f\u004d\u0070\u004e\u0053\u0066\u0053\u0028\u007a\u0029\u0050\u0073\u0041\u007d\u0072\u0074\u0078\u0067\u004e\u006a\u0037\u002e\u0069\u0028\u0042\u0023\u002d\u005d\u0034\u003b\u0079\u0021\u0034\u0032\u0041\u0058\u0077\u003e\u0065\u0042\u002d\u0020\u007b\u002d\u006a\u0034\u007b\u0055\u0066\u0049\u0035\u005b\u0046\u0069\u0051\u0035\u0058\u0056\u004c\u004e\u007e\u0076\u0032\u0037\u0032\u0021\u007e\u002c\u0078\u0046\u0044\u0063\u005b\u005e\u0032\u0070\u0043\u0075\u002b\u0052